import React, { Component } from "react";
import "./Aboutus.css";

export default class Aboutus extends Component {
    render() {
        return (
            <div>
                <></><a className="title">TaiLink</a>
                <p>TaiLink helps locate lost or stolen pets through the use of a microchip implanted in them.
                    Our website has many feature:</p>
                <p>1.allowing those who found the pets to conversate with the owners.</p> 
                <p> 2.Enabling them to provide updates via the chip's identification number.</p> 
                <p>3.Users can also post information about lost pets that have not yet been found or animals in need of assistance.</p> 
                <p>4.Suggestions for veterinary services or suitable homes can also be provided.</p> 

            </div>
        );
    }
}
